export function emptyLearning(){return {version:1,courses:{},projects:{}};}
export function courseRecord(state,id){return state.courses[id]||{read:[],answers:{},evidence:'',practice:false};}
export function updateCourse(state,id,patch){return {...state,courses:{...state.courses,[id]:{...courseRecord(state,id),...patch}}};}
export function assessmentPassed(record,course){return course.questions.every((q,i)=>record.answers[i]===q.correct);}
export function courseCheckpoint(state,course){const r=courseRecord(state,course.id);return course.lessons.every((_,i)=>r.read.includes(i))&&assessmentPassed(r,course)&&r.practice&&r.evidence.trim().length>=80;}
export function parseLearning(raw,courses,projects){try{const d=JSON.parse(raw);if(d?.version!==1)return emptyLearning();const clean=emptyLearning();for(const c of courses){const r=d.courses?.[c.id];if(!r||typeof r!=='object')continue;const answers={};for(let i=0;i<c.questions.length;i++){const a=r.answers?.[i];if(Number.isInteger(a)&&a>=0&&a<c.questions[i].options.length)answers[i]=a;}clean.courses[c.id]={read:[...new Set((Array.isArray(r.read)?r.read:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<c.lessons.length))],answers,evidence:typeof r.evidence==='string'?r.evidence.slice(0,5000):'',practice:r.practice===true};}for(const p of projects){const value=d.projects?.[p.id];if(value&&typeof value==='object'){clean.projects[p.id]={};p.milestones.forEach((m,i)=>{const r=value[i];if(r&&typeof r==='object')clean.projects[p.id][i]={evidence:typeof r.evidence==='string'?r.evidence.slice(0,5000):'',done:r.done===true};});}}return clean;}catch{return emptyLearning();}}
export function prerequisiteOrder(courses){const result=[],visiting=new Set(),visited=new Set();const walk=id=>{if(visiting.has(id))throw new Error('Cyclic course prerequisites');if(visited.has(id))return;const c=courses.find(c=>c.id===id);if(!c)throw new Error('Unknown prerequisite '+id);visiting.add(id);c.prerequisites.forEach(walk);visiting.delete(id);visited.add(id);result.push(c);};courses.forEach(c=>walk(c.id));return result;}
